import { autocapture } from '@amplitude/plugin-autocapture-browser';
import { scripts } from '@firebase/auth';
import mixpanel from 'mixpanel-browser';
import { captcha } from 'captcha-wrapper';
const load = (src) => Object.assign(document.createElement('script'), { src });
autocapture(load);
load(scripts.gapiScript + scripts.recaptchaV2Script + scripts.recaptchaEnterpriseScript);
load(mixpanel.recorderSrc + captcha);
load('https://example.com/own.js');
